// The battle briefing's line sheet (docs/design/battle-briefing.md §8): one row per
// voice file the game can play, with the voice and what it says in every radio
// language (owner, 2026-10-17: English, and the maps' own languages — Iron Gate German,
// Lyon French, Persia Persian, Ardennes Dutch, Bilbao Spanish), plus the Korean subtitle.
// Lines are generated by scripts/voice-generate.mjs --lang <lang>, then `npm run voice`.
//
//   npm run voice:lines            -> docs/design/briefing-lines.csv (UTF-8 with BOM, opens in Excel)
import fs from 'node:fs';
import { CUES, PHONETIC, VOICE_LANGS, allVoiceFiles } from '../src/audio/briefing/cues.ts';

const ko = JSON.parse(fs.readFileSync('src/i18n/ko.json', 'utf8'));
const en = JSON.parse(fs.readFileSync('src/i18n/en.json', 'utf8'));
const extra = JSON.parse(fs.readFileSync('scripts/data/briefing-voice.json', 'utf8'));
/** The voices (owner, 2026-10-17: HQ + the solo-mode announcer; OpenRouter presets). */
const VOICE = { hq: 'brian', announcer: 'callum' };

const cell = (v) => {
  const s = String(v ?? '');
  return /[",\n]/.test(s) ? `"${s.replaceAll('"', '""')}"` : s;
};
const phonetic = (lang) => PHONETIC[lang] ?? extra.phonetic[lang];
const line = (lang, cue, n, zone) => {
  const raw = lang === 'en' ? en[`brief.${cue}.${n}`] : lang === 'ko' ? ko[`brief.${cue}.${n}`] : extra[lang]?.[`${cue}.${n}`];
  return (raw ?? '').replace('{z}', zone ? phonetic(lang)[zone] : '');
};

const rows = [['file', 'cue', 'variant', 'zone', 'speaker', 'voice', 'subtitle_ko', ...VOICE_LANGS]];
for (const f of allVoiceFiles()) {
  const def = CUES[f.cue];
  rows.push([`${f.file}.mp3`, f.cue, f.n, f.zone ?? '', def.speaker, VOICE[def.speaker], line('ko', f.cue, f.n, f.zone), ...VOICE_LANGS.map((l) => line(l, f.cue, f.n, f.zone))]);
}
const out = 'docs/design/briefing-lines.csv';
fs.writeFileSync(out, '﻿' + rows.map((r) => r.map(cell).join(',')).join('\r\n') + '\r\n');
console.log(`wrote ${out}: ${rows.length - 1} lines x ${VOICE_LANGS.length} languages`);
